CREATE TABLE IF NOT EXISTS public.users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text,
  email text UNIQUE,
  phone text,
  role text,
  "profileImage" text,
  bio text,
  location text,
  wilaya text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.property_categories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  "nameAr" text,
  "nameFr" text,
  icon text,
  type text,
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.properties (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title text NOT NULL,
  description text,
  type text,
  price numeric,
  currency text,
  bedrooms integer,
  bathrooms integer,
  area numeric,
  address text,
  wilaya text,
  commune text,
  latitude numeric,
  longitude numeric,
  images text[],
  amenities text[],
  status text,
  "agentId" uuid REFERENCES public.users(id) ON DELETE SET NULL,
  "isVerified" boolean DEFAULT false,
  views integer DEFAULT 0,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.agents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  license text,
  "verificationStatus" text,
  rating numeric DEFAULT 0,
  "reviewCount" integer DEFAULT 0,
  "totalListings" integer DEFAULT 0,
  bio text,
  specializations text[],
  "responseTime" text,
  languages text[],
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.favorites (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  "propertyId" uuid NOT NULL REFERENCES public.properties(id) ON DELETE CASCADE,
  created_at timestamptz DEFAULT now(),
  UNIQUE("userId", "propertyId")
);

CREATE TABLE IF NOT EXISTS public.conversations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  participants uuid[] NOT NULL,
  "propertyId" uuid REFERENCES public.properties(id) ON DELETE SET NULL,
  "unreadCount" integer DEFAULT 0,
  updated_at timestamptz DEFAULT now(),
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.messages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "conversationId" uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,
  "senderId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  "receiverId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  "propertyId" uuid REFERENCES public.properties(id) ON DELETE SET NULL,
  content text,
  read boolean DEFAULT false,
  timestamp timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.appointments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "buyerId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  "agentId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  "propertyId" uuid NOT NULL REFERENCES public.properties(id) ON DELETE CASCADE,
  "scheduledTime" timestamptz,
  status text,
  notes text,
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.reviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "authorId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  "agentId" uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  rating integer,
  comment text,
  created_at timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_properties_agentId ON public.properties("agentId");
CREATE INDEX IF NOT EXISTS idx_properties_wilaya ON public.properties(wilaya);
CREATE INDEX IF NOT EXISTS idx_properties_status ON public.properties(status);
CREATE INDEX IF NOT EXISTS idx_properties_created_at ON public.properties(created_at);
CREATE INDEX IF NOT EXISTS idx_favorites_userId ON public.favorites("userId");
CREATE INDEX IF NOT EXISTS idx_favorites_propertyId ON public.favorites("propertyId");
CREATE INDEX IF NOT EXISTS idx_messages_conversationId ON public.messages("conversationId");
CREATE INDEX IF NOT EXISTS idx_messages_senderId ON public.messages("senderId");
CREATE INDEX IF NOT EXISTS idx_messages_receiverId ON public.messages("receiverId");
CREATE INDEX IF NOT EXISTS idx_messages_timestamp ON public.messages(timestamp);
CREATE INDEX IF NOT EXISTS idx_appointments_buyerId ON public.appointments("buyerId");
CREATE INDEX IF NOT EXISTS idx_appointments_agentId ON public.appointments("agentId");
CREATE INDEX IF NOT EXISTS idx_appointments_propertyId ON public.appointments("propertyId");
CREATE INDEX IF NOT EXISTS idx_appointments_scheduledTime ON public.appointments("scheduledTime");
CREATE INDEX IF NOT EXISTS idx_reviews_authorId ON public.reviews("authorId");
CREATE INDEX IF NOT EXISTS idx_reviews_agentId ON public.reviews("agentId");
CREATE INDEX IF NOT EXISTS idx_agents_userId ON public.agents("userId");

ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.favorites ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.property_categories ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own profile" ON public.users FOR SELECT USING (auth.uid() = id);
CREATE POLICY "Users can update own profile" ON public.users FOR UPDATE USING (auth.uid() = id);
CREATE POLICY "Public can view user profiles" ON public.users FOR SELECT USING (true);

CREATE POLICY "Anyone can view properties" ON public.properties FOR SELECT USING (true);
CREATE POLICY "Agents can insert properties" ON public.properties FOR INSERT WITH CHECK (auth.uid() = "agentId");
CREATE POLICY "Agents can update own properties" ON public.properties FOR UPDATE USING (auth.uid() = "agentId");
CREATE POLICY "Agents can delete own properties" ON public.properties FOR DELETE USING (auth.uid() = "agentId");

CREATE POLICY "Users can view own agent profile" ON public.agents FOR SELECT USING (auth.uid() = "userId" OR true);
CREATE POLICY "Public can view agent profiles" ON public.agents FOR SELECT USING (true);

CREATE POLICY "Users can view own favorites" ON public.favorites FOR SELECT USING (auth.uid() = "userId");
CREATE POLICY "Users can insert own favorites" ON public.favorites FOR INSERT WITH CHECK (auth.uid() = "userId");
CREATE POLICY "Users can delete own favorites" ON public.favorites FOR DELETE USING (auth.uid() = "userId");

CREATE POLICY "Users can view own messages" ON public.messages FOR SELECT USING (auth.uid() = "senderId" OR auth.uid() = "receiverId");
CREATE POLICY "Users can insert messages" ON public.messages FOR INSERT WITH CHECK (auth.uid() = "senderId");
CREATE POLICY "Users can update own messages" ON public.messages FOR UPDATE USING (auth.uid() = "senderId");

CREATE POLICY "Users can view conversations" ON public.conversations FOR SELECT USING (auth.uid() = ANY(participants));
CREATE POLICY "Users can insert conversations" ON public.conversations FOR INSERT WITH CHECK (auth.uid() = ANY(participants));
CREATE POLICY "Users can update conversations" ON public.conversations FOR UPDATE USING (auth.uid() = ANY(participants));

CREATE POLICY "Users can view own appointments" ON public.appointments FOR SELECT USING (auth.uid() = "buyerId" OR auth.uid() = "agentId");
CREATE POLICY "Users can insert appointments" ON public.appointments FOR INSERT WITH CHECK (auth.uid() = "buyerId");
CREATE POLICY "Users can update own appointments" ON public.appointments FOR UPDATE USING (auth.uid() = "buyerId" OR auth.uid() = "agentId");

CREATE POLICY "Users can view reviews" ON public.reviews FOR SELECT USING (true);
CREATE POLICY "Users can insert reviews" ON public.reviews FOR INSERT WITH CHECK (auth.uid() = "authorId");

CREATE POLICY "Anyone can view categories" ON public.property_categories FOR SELECT USING (true);

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO public.users (id, email, name, phone, role, "profileImage", bio, location, wilaya, created_at, updated_at)
  VALUES (
    NEW.id,
    NEW.email,
    NEW.raw_user_meta_data ->> 'name',
    NEW.raw_user_meta_data ->> 'phone',
    NEW.raw_user_meta_data ->> 'role',
    NEW.raw_user_meta_data ->> 'profileImage',
    NEW.raw_user_meta_data ->> 'bio',
    NEW.raw_user_meta_data ->> 'location',
    NEW.raw_user_meta_data ->> 'wilaya',
    now(),
    now()
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- === Deterministic CRUD policies for user-owned tables (generated by SupabaseConfigAgent) ===
