DROP POLICY IF EXISTS "Users can update own appointments" ON public."appointments";
CREATE POLICY "Users can update own appointments" ON public."appointments" FOR UPDATE USING (auth.uid() = "buyerId") WITH CHECK (auth.uid() = "buyerId");
